/* Joint bundle review. Draft poses never change the main workspace before Apply. */
'use strict';
(()=>{
 const dialog=document.createElement('dialog');dialog.id='bundle-adjustment-dialog';dialog.className='ts-analysis-dialog';
 const el=id=>document.getElementById('ba-'+id),fmt=v=>Number.isFinite(v)?v.toFixed(3):'—';
 let graph=null,loops=[],token=null,result=null,working=false,inspecting=false,generation=0,frame='plan',after=true,zoom=1,pan=[0,0],drag=null;
 dialog.innerHTML=`<header><div><h2>Bundle adjustment & loop closure</h2><p>Adjust all connected setups together. Choose the reference that must stay fixed.</p></div><button id="ba-close" aria-label="Close bundle adjustment">×</button></header>
 <div class="ts-analysis-settings"><label>Fixed reference<select id="ba-anchor"></select></label><label>Sampling<select id="ba-quality"><option value="fast">Fast</option><option value="balanced" selected>Balanced</option><option value="high">High</option></select></label><label>Residual review level (mm)<input id="ba-tolerance" type="number" min=".01" max="1000" value="5" step=".1"></label><label>Cloud search distance (mm)<input id="ba-capture" type="number" min="1" max="10000" value="250"></label></div>
 <p id="ba-group"></p><div class="ts-analysis-split"><section><h3>Loop candidates</h3><p>Choose setups that see the same physical surfaces. Suggested pairs only have overlapping bounds; they still require validation.</p><div class="ts-analysis-settings"><label>First setup<select id="ba-a"></select></label><label>Second setup<select id="ba-b"></select></label><button id="ba-add">Add loop pair</button></div><div id="ba-loops"></div><details><summary id="ba-suggestion-label">Possible overlaps</summary><div id="ba-suggestions"></div></details><button id="ba-run" class="primary">Adjust bundle</button><button id="ba-stop" hidden>Stop adjustment</button></section>
 <section class="ts-analysis-preview"><nav aria-label="Bundle preview controls"><button data-ba-view="plan">Plan</button><button data-ba-view="side">Side elevation</button><button data-ba-view="front">Front elevation</button><button id="ba-before">Before</button><button id="ba-after" class="chosen">After</button><button id="ba-fit">Fit</button></nav><canvas id="ba-canvas" aria-label="Sampled bundle preview: fixed setup blue, adjusted setups orange" tabindex="0"></canvas><p>Blue: fixed reference · Orange: adjustable setups · Bounded display samples · Drag to pan, wheel to zoom</p></section></div>
 <section id="ba-review" hidden><div id="ba-summary"></div><div class="ts-analysis-table"><table><thead><tr><th>Link</th><th>Type</th><th>Target RMS (mm)</th><th>Plane RMS before → after (mm)</th><th>Distinct overlap</th></tr></thead><tbody id="ba-links"></tbody></table></div><details><summary>Setup movements</summary><div id="ba-movements"></div></details><div id="ba-warnings"></div></section>
 <footer><p id="ba-status" role="status" aria-live="polite">Select a connected bundle.</p><button id="ba-apply" class="primary" disabled>Apply reviewed adjustment</button></footer>`;
 document.body.append(dialog);
 const message=(text,error=false)=>{el('status').textContent=text;el('status').classList.toggle('error',error);};
 function controls(){const pending=working||inspecting;for(const x of dialog.querySelectorAll('input,select,#ba-run,#ba-add,[data-ba-suggest],[data-ba-remove]'))x.disabled=pending;el('close').disabled=working;el('stop').hidden=!working;el('apply').disabled=pending||!result;el('run').disabled=pending||!graph||graph.scans.length<2;}
 function invalidate(){generation++;token=null;result=null;el('review').hidden=true;controls();draw();}
 const name=id=>graph?.scans.find(s=>s.id===id)?.name||id;
 function renderLoops(){el('loops').innerHTML=loops.map((x,i)=>`<p>${esc(name(x.a))} ↔ ${esc(name(x.b))} <button data-ba-remove="${i}" aria-label="Remove loop candidate">Remove</button></p>`).join('')||'<p>No additional loop pairs. Existing links are included.</p>';for(const x of el('loops').querySelectorAll('button'))x.onclick=()=>{loops.splice(+x.dataset.baRemove,1);invalidate();renderLoops();};controls();}
 function add(a,b){if(working||inspecting||!graph)return;if(a===b||!a||!b){message('Choose two different setups.',true);return;}if([...loops,...graph.links].some(x=>x.a===a&&x.b===b||x.a===b&&x.b===a)){message('That pair already has a link or candidate.',true);return;}loops.push({a,b});invalidate();renderLoops();message('Loop candidate added. Adjust the bundle to validate and review it.');}
 async function inspect(){invalidate();const stamp=generation;inspecting=true;loops=[];graph=null;el('group').textContent='Reading connected setups…';for(const key of ['a','b','suggestions'])el(key).replaceChildren();el('suggestion-label').textContent='Possible overlaps';renderLoops();message('Reading connected setups…');try{const value=await post('/api/scan-registration',{action:'bundle_inspect',anchor:el('anchor').value});if(stamp!==generation)return;graph=value;el('group').textContent=`${value.scans.length} setups · ${value.links.length} saved links · ${value.cycle_count} independent loops`;for(const key of ['a','b'])el(key).innerHTML=value.scans.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');if(value.scans.length>1)el('b').selectedIndex=1;el('suggestion-label').textContent=`Possible overlaps (${value.suggestions.length} shown of ${value.suggestions_total})`;el('suggestions').innerHTML=value.suggestions.map((x,i)=>`<button data-ba-suggest="${i}">${esc(name(x.a))} ↔ ${esc(name(x.b))}</button>`).join('')||'<p>No additional overlapping bounds found. You can still choose a pair above.</p>';for(const x of el('suggestions').querySelectorAll('button'))x.onclick=()=>{const pair=value.suggestions[+x.dataset.baSuggest];add(pair.a,pair.b);};renderLoops();message('Existing target and cloud links will be adjusted together. No changes until Apply.');}catch(e){if(stamp===generation)message(e.message,true);}finally{if(stamp===generation){inspecting=false;controls();}}}
 function review(value){result=value;const s=value.solution;el('review').hidden=false;el('summary').textContent=`${s.fallback_used?'Pairwise fallback · full bundle did not converge · ':''}${s.scan_count} setups · ${s.common_targets} shared targets (${s.target_observations} observations) · ${s.cycle_count} loops · Target RMS ${fmt(s.target_fit.rms_mm)} mm · Plane RMS ${fmt(s.cloud_fit.rms_mm)} mm · Independent check RMS ${fmt(s.check.rms_mm)} mm`;
  el('links').innerHTML=s.edge_reports.map(x=>`<tr><td>${esc(x.a)} ↔ ${esc(x.b)}</td><td>${x.loop_closure?'Loop':'Link'}</td><td>${fmt(x.target_fit?.rms_mm)}</td><td>${fmt(x.cloud?.before.rms_mm)} → ${fmt(x.cloud?.after.rms_mm)}</td><td>${x.cloud?.inlier_count??'—'}</td></tr>`).join('');el('movements').innerHTML='<table><thead><tr><th>Setup</th><th>Centre movement (mm)</th><th>Rotation (°)</th></tr></thead><tbody>'+value.preview.map(x=>`<tr><td>${esc(x.name)}${x.fixed?' · held fixed':''}</td><td>${fmt(x.shift_mm)}</td><td>${fmt(x.rotation_deg)}</td></tr>`).join('')+'</tbody></table>';el('warnings').replaceChildren(...s.warnings.map(x=>{const p=document.createElement('p');p.textContent=x;return p;}));zoom=1;pan=[0,0];controls();draw();}
 el('run').onclick=async()=>{if(working||inspecting||!graph||graph.scans.length<2)return;invalidate();working=true;controls();message('Reading retained points and adjusting the bundle…');const stamp=generation;try{const started=await post('/api/scan-registration',{action:'bundle_preview',anchor:el('anchor').value,quality:el('quality').value,tolerance_mm:+el('tolerance').value,capture_mm:+el('capture').value,loops});token=started.token;await window.JobUI.waitReady(p=>{if(p.busy)message(p.message||'Adjusting bundle…');},{skipSync:true});if(stamp!==generation)return;const value=await post('/api/scan-registration',{action:'bundle_status',token});if(value.state!=='ready')throw Error(value.reason||'Bundle adjustment did not produce a reviewable result.');review(value);message('Review the link residuals, setup movements and preview. Apply saves all adjusted poses together.');}catch(e){result=null;message(e.message,true);}finally{working=false;controls();}};
 el('stop').onclick=async()=>{el('stop').disabled=true;try{await post('/api/cancel-operation',{});message('Stopping adjustment…');}catch(e){message(e.message,true);}finally{el('stop').disabled=false;}};
 el('apply').onclick=async()=>{if(working||!result)return;working=true;controls();try{const applied=await post('/api/scan-registration',{action:'bundle_apply',token});result=null;dialog.close();await window.JobUI.sync();await poll();await window.JobUI.loadPreview();notice(applied.fallback_used?'Full bundle adjustment did not converge. A pairwise adjustment was applied instead. Review residuals before measurement use.':'Bundle adjustment saved. The reference stayed fixed. Workspace Undo restores the previous poses and links.');}catch(e){result=null;message(e.message,true);}finally{working=false;controls();}};
 el('anchor').onchange=inspect;for(const id of ['quality','tolerance','capture'])el(id).onchange=()=>{invalidate();message('Settings changed. Adjust again before applying.');};el('add').onclick=()=>add(el('a').value,el('b').value);
 function close(){if(working){message('Stop the adjustment before closing.');return;}invalidate();inspecting=false;controls();dialog.close();}el('close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 const canvas=el('canvas');function draw(){const ctx=canvas.getContext('2d'),box=canvas.getBoundingClientRect();if(!box.width||!box.height)return;const ratio=window.devicePixelRatio||1;canvas.width=Math.round(box.width*ratio);canvas.height=Math.round(box.height*ratio);ctx.scale(ratio,ratio);ctx.fillStyle='#0b1b24';ctx.fillRect(0,0,box.width,box.height);const clouds=result?.preview||[];if(!clouds.length){ctx.fillStyle='#b5cbd6';ctx.font='14px system-ui';ctx.fillText('Run adjustment to review the bundle',20,35);return;}const axes=frame==='plan'?[0,1]:frame==='side'?[0,2]:[1,2];let lo=[Infinity,Infinity],hi=[-Infinity,-Infinity];for(const c of clouds)for(const p of c[after?'after':'before'])for(let a=0;a<2;a++){lo[a]=Math.min(lo[a],p[axes[a]]);hi[a]=Math.max(hi[a],p[axes[a]]);}const scale=Math.min((box.width-30)/Math.max(.01,hi[0]-lo[0]),(box.height-30)/Math.max(.01,hi[1]-lo[1]))*zoom,centre=lo.map((x,i)=>(x+hi[i])/2);for(const c of clouds){ctx.fillStyle=c.fixed?'#39b6ff':'#ffad5a';ctx.globalAlpha=.65;for(const p of c[after?'after':'before'])ctx.fillRect(box.width/2+(p[axes[0]]-centre[0])*scale+pan[0],box.height/2-(p[axes[1]]-centre[1])*scale+pan[1],1.5,1.5);}ctx.globalAlpha=1;}
 for(const b of dialog.querySelectorAll('[data-ba-view]'))b.onclick=()=>{frame=b.dataset.baView;pan=[0,0];zoom=1;draw();};el('before').onclick=()=>{after=false;el('after').classList.remove('chosen');el('before').classList.add('chosen');draw();};el('after').onclick=()=>{after=true;el('before').classList.remove('chosen');el('after').classList.add('chosen');draw();};el('fit').onclick=()=>{pan=[0,0];zoom=1;draw();};canvas.onwheel=e=>{e.preventDefault();zoom=Math.max(.1,Math.min(50,zoom*Math.exp(-e.deltaY*.001)));draw();};canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY,...pan];canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(drag){pan=[drag[2]+e.clientX-drag[0],drag[3]+e.clientY-drag[1]];draw();}};canvas.onpointerup=canvas.onpointercancel=()=>{drag=null;};new ResizeObserver(draw).observe(canvas);
 window.BundleAdjustmentUI={open:async()=>{if(busy||working||inspecting)return;try{if(window.TunnelRibbon?.prepareTool?.('measure')===false)return;await window.TargetUI?.saveIfDirty();const network=await api('/api/scan-registration');el('anchor').innerHTML=network.scans.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');const first=network.links[0]?.a;if(first)el('anchor').value=first;dialog.showModal();await inspect();}catch(e){notice(e.message,true);}}};
})();
